metrics.workdir_dsl:
workspace "Claims Center" "The insurance company's claims platform: policyholders report claims and track their progress, and staff process them to settlement." {

    model {

        policyholder = person "Policyholder" "Reports claims and tracks their progress through the Claims Center."
        adjuster = person "Adjuster" "Processes assigned claims in the adjuster workbench."

        claimsBureau = softwareSystem "National Claims Data Bureau" "A national claims data bureau operated by a different organization, consulted for fraud screening." "External"
        clearingHouse = softwareSystem "Clearing House" "A clearing house operated by a different organization, through which claim settlements are executed." "External"

        claimsCenter = softwareSystem "Claims Center" "The insurance company's claims platform. Policyholders report claims and track their progress, and staff process them to settlement." {

            webPortal = container "Web Portal" "Where policyholders report claims and track their progress." "Web application" "Web"
            mobileBackend = container "Mobile App Backend" "Serves the insurer's mobile app." "API service"
            intake = container "Claims Intake Service" "Registers new claims." "Microservice"
            triage = container "Triage Service" "Classifies and prioritizes claims." "Microservice"
            assessment = container "Assessment Service" "Calculates settlement amounts." "Microservice"
            payout = container "Payout Service" "Executes claim settlements." "Microservice"
            fraud = container "Fraud Screening Service" "Flags suspicious claims." "Microservice"
            document = container "Document Service" "Accepts claim photos and reports." "Microservice"
            notification = container "Notification Service" "Emails and messages policyholders." "Microservice"
            assignment = container "Assignment Service" "Routes claims to adjusters." "Microservice"
            workbench = container "Adjuster Workbench" "Where staff process their assigned claims." "Web application" "Web"
            policyVerification = container "Policy Verification Service" "Checks that a claim is covered by the policy." "Microservice"
            reinsurance = container "Reinsurance Allocation Service" "Apportions large losses across reinsurance partners." "Microservice"
            batchScheduler = container "Batch Scheduler" "Runs the nightly reserves calculation." "Batch job"
            eventQueue = container "Event Queue" "Carries claim events between the application parts." "Message queue" "Queue"
            claimsDb = container "Claims Database" "Stores claim records." "Relational database" "Database"
            policyDb = container "Policy Database" "Stores policy and cover records." "Relational database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail." "Relational database" "Database"
            documentStore = container "Document Store" "Holds claim photos, reports, and correspondence." "Object storage" "Database"
        }

        policyholder -> webPortal "Reports claims and tracks their progress in" "HTTPS"
        policyholder -> mobileBackend "Reports claims and tracks their progress through the insurer's mobile app" "HTTPS"
        adjuster -> workbench "Processes assigned claims in" "HTTPS"

        fraud -> claimsBureau "Consults for fraud screening" "REST/JSON"
        payout -> clearingHouse "Executes settlements through" "REST/JSON"

        webPortal -> intake "Submits new claims to" "REST/JSON"
        webPortal -> assessment "Requests settlement assessments from" "REST/JSON"
        webPortal -> payout "Requests claim settlements from" "REST/JSON"
        webPortal -> document "Uploads claim photos and reports to" "REST/JSON"
        webPortal -> notification "Requests status notifications from" "REST/JSON"
        mobileBackend -> intake "Submits new claims to" "REST/JSON"
        mobileBackend -> assessment "Requests settlement assessments from" "REST/JSON"
        mobileBackend -> payout "Requests claim settlements from" "REST/JSON"
        mobileBackend -> document "Uploads claim photos and reports to" "REST/JSON"
        mobileBackend -> notification "Requests status notifications from" "REST/JSON"

        intake -> triage "Hands accepted claims to" "REST/JSON"
        triage -> assessment "Routes claims to" "REST/JSON"
        assessment -> payout "Requests settlements from" "REST/JSON"

        intake -> fraud "Sends each incoming claim to for screening" "REST/JSON"
        intake -> policyVerification "Sends the claim to for cover verification" "REST/JSON"
        assignment -> workbench "Routes the claim to" "REST/JSON"

        document -> documentStore "Reads claim photos and reports from" "Object storage API"
        batchScheduler -> claimsDb "Reads and writes claim records in" "SQL"
        batchScheduler -> policyDb "Reads and writes policy records in" "SQL"

        notification -> policyholder "Reports claim status changes to" "Email/SMS"
    }

    views {
        systemContext claimsCenter "SystemContext" {
            include *
            autoLayout
            title "System Context for Claims Center"
        }
        container claimsCenter "Containers" {
            include *
            autoLayout
            title "Containers for Claims Center"
        }
        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            element "Queue" {
                shape Pipe
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
